<?php $base='../';require_once '../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$rid=(int)$_POST['request_id'];db()->prepare('INSERT INTO quotations(request_id,amount,details,valid_until) VALUES(?,?,?,?)')->execute([$rid,$_POST['amount'],$_POST['details'],$_POST['valid_until']?:null]);db()->prepare("UPDATE service_requests SET status='Quotation Sent' WHERE request_id=?")->execute([$rid]);$q=db()->prepare('SELECT customer_id FROM service_requests WHERE request_id=?');$q->execute([$rid]);$uid=$q->fetchColumn();db()->prepare('INSERT INTO notifications(user_id,message) VALUES(?,?)')->execute([$uid,'A quotation has been sent for your request.']);flash('success','Quotation sent.');header('Location: quotations.php');exit;}$rows=db()->query("SELECT r.request_id,r.project_title,u.full_name,s.service_name FROM service_requests r JOIN users u ON u.user_id=r.customer_id JOIN services s ON s.service_id=r.service_id WHERE r.status IN ('Reviewed','Quotation Sent') ORDER BY r.created_at DESC")->fetchAll();$title='Quotations';include '../includes/header.php';?><section class="section"><div class="container"><h1>Quotations</h1><?php show_flash();?><div class="row g-4 mt-2"><?php foreach($rows as $r):?><div class="col-md-6"><form method="post" class="card p-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="request_id" value="<?=$r['request_id']?>"><h4><?=e($r['project_title'])?></h4><p class="gold"><?=e($r['full_name'])?> · <?=e($r['service_name'])?></p><input class="form-control mb-2" name="amount" type="number" step=".01" placeholder="Amount (ETB)" required><textarea class="form-control mb-2" name="details" placeholder="Quotation details" required></textarea><input class="form-control mb-2" name="valid_until" type="date"><button class="btn btn-gold">Send Quotation</button></form></div><?php endforeach;?></div></div></section><?php include '../includes/footer.php';?>
